INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('lilian-weng-transformer-family-v2', 'The Transformer Family Version 2.0', 'Lilian Weng updates her canonical transformer survey with sparse attention, long-context variants, state-space hybrids, and the architectural trade-offs that matter for modern LLMs. It remains the best single post for mapping encoder-only, decoder-only, and encoder-decoder families, though some frontier variants postdate the 2023 write-up.', 'Lilian Weng', 'https://github.com/lilianweng.png', 'LLM & MLLM', ARRAY['Transformers','Architecture Survey','Attention','Long Context'], '35 min read', '2023-01-27', 'Lil''Log', 'https://lilianweng.github.io/posts/2023-01-27-the-transformer-family-v2/', 'assets/img/covers/real/expand-parent/lilian-transformer-family-v2.png', 'Transformer family architecture diagram', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('huggingface-optimizing-llm-in-production', 'Optimizing your LLM in production', 'Hugging Face walks through the production bottlenecks of LLM inference—quadratic attention memory, KV-cache growth, positional encoding choices, and Flash Attention—with concrete guidance for deployment. The recommendations reflect the HF/TGI stack circa publication and may omit vendor-specific serving features added later.', 'Hugging Face', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', ARRAY['LLM Inference','Flash Attention','KV Cache','Production'], '18 min read', '2023-06-27', 'Hugging Face Blog', 'https://huggingface.co/blog/optimize-llm', 'assets/img/covers/real/expand-parent/hf-optimize-llm.png', 'LLM optimization diagram from Hugging Face', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('interconnects-state-of-reasoning', 'The State of Reasoning', 'Nathan Lambert surveys how reasoning models, RL post-training, and benchmark inflation changed the open-model landscape in late 2024, separating marketing claims from reproducible capability gains. The post is opinionated toward open-weight labs and predates several 2025–2026 reasoning releases.', 'Nathan Lambert', 'https://github.com/natolambert.png', 'Frontier', ARRAY['Reasoning Models','RLHF','Open Models','Benchmarks'], '20 min read', '2025-01-01', 'Interconnects', 'https://www.interconnects.ai/p/the-state-of-reasoning', 'assets/img/covers/real/expand-parent/nathan-state-of-reasoning.jpg', 'Interconnects reasoning models cover', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('eugene-yan-llm-patterns', 'Patterns for Building LLM-based Systems & Products', 'Eugene Yan catalogs recurring design patterns for LLM products—routing, caching, guardrails, eval loops, and human-in-the-loop fallbacks—grounded in applied ML systems experience rather than research novelty. The patterns are descriptive, not prescriptive benchmarks, and predate agent-native architectures.', 'Eugene Yan', 'https://github.com/eugeneyan.png', 'Research Craft', ARRAY['LLM Patterns','Product Design','Evaluation','Applied ML'], '22 min read', '2023-12-19', 'eugeneyan.com', 'https://eugeneyan.com/writing/llm-patterns/', 'assets/img/covers/real/expand-parent/eugene-llm-patterns.png', 'LLM system patterns illustration', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('simon-willison-llm-intros', 'Large language models are having a Stable Diffusion moment', 'Simon Willison explains why locally runnable LLMs felt like Stable Diffusion all over again—sudden capability jumps, messy tooling, and a flood of experiments—and outlines practical ways developers can explore models safely. The 2023 framing remains useful history even as hosted APIs narrowed the gap.', 'Simon Willison', 'https://github.com/simonw.png', 'LLM & MLLM', ARRAY['Local LLMs','Developer Tools','LLaMA','AI Accessibility'], '12 min read', '2023-04-02', 'Simon Willison''s Weblog', 'https://simonwillison.net/2023/Apr/2/llm-intros/', 'assets/img/covers/real/expand-parent/simon-llm-intros.png', 'Simon Willison LLM introduction cover', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
INSERT INTO blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit) VALUES ('huggingface-tgi-inference-at-scale', 'LLM Inference at scale with TGI', 'Martín Iglesias dissects Hugging Face Text Generation Inference from warmup through continuous batching, KV caching, and Paged Attention, using Adyen''s production deployment as a case study. Throughput numbers are tied to specific hardware and TGI versions from the write-up period.', 'Martín Iglesias', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'Efficient AI', ARRAY['Text Generation Inference','Continuous Batching','KV Cache','Serving'], '15 min read', '2024-03-15', 'Hugging Face Blog', 'https://huggingface.co/blog/martinigoyanes/llm-inference-at-scale-with-tgi', 'assets/img/covers/real/expand-parent/hf-tgi-at-scale.png', 'TGI inference at scale diagram', 'cover') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, excerpt=EXCLUDED.excerpt, url=EXCLUDED.url;
